window.STUDIA_CARDS=[{"id": "edukacja/fiszki:967ffdf1", "q": "Dlaczego autorka wybiera termin „psychologia edukacyjna”, a nie „wychowawcza” czy „wychowania”?", "a": "<p>Z dwóch powodów: potrzeby nawiązania do głównego nurtu refleksji i badań międzynarodowych (ang. <em>educational psychology</em>) oraz instytucjonalnego charakteru procesu edukacji. Ani „wychowawcza”, ani „wychowania” nie mają jednoznacznego odpowiednika w języku angielskim.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["nawiązanie do nurtu międzynarodowego (educational psychology)", "instytucjonalny charakter edukacji"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:8c0f5e98", "q": "Czym w rozdziale różni się wychowanie od edukacji (kształcenia)?", "a": "<p>Wychowanie odbywa się głównie (choć nie tylko) w kontekście <strong>domowym</strong> i dotyczy kształtowania zachowania. Edukacja (kształcenie) odbywa się głównie (choć nie tylko) w kontekście <strong>instytucjonalnym</strong> i dotyczy umiejętności szkolnych i akademickich. Dawniej „wychowanie” obejmowało jedno i drugie; z czasem pole znaczeniowe się rozszczepiło.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["wychowanie: dom, zachowanie", "edukacja: instytucja, umiejętności szkolne", "rozszczepienie pola znaczeniowego"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:d386a5fd", "q": "Czym psychologia kształcenia różni się od psychologii edukacyjnej?", "a": "<p>Psychologia kształcenia obejmuje część teoretyczno-koncepcyjną i badania podstawowe nad nabywaniem umiejętności szkolnych i akademickich, a aspekty praktyczne w znacznie mniejszym stopniu. Psychologię edukacyjną wyróżnia <strong>aplikacyjny kontekst</strong>: jest dyscypliną stosowaną.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["kształcenie: teoria i badania podstawowe", "edukacyjna: kontekst aplikacyjny (stosowana)"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:e57d99b8", "q": "Jakim celom służy psychologia edukacyjna jako dyscyplina stosowana?", "a": "<p>Podnoszeniu dobrostanu uczniów w ogóle, rozwiązywaniu problemów behawioralnych w placówkach edukacyjnych i optymalizowaniu efektów uczenia się u wszystkich kształcących się, szczególnie w grupach doświadczających trudności i barier. W wielu krajach wymaga odrębnego kształcenia podyplomowego.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["dobrostan uczniów", "problemy behawioralne w placówkach", "optymalizacja efektów uczenia się"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:d1d3b36d", "q": "Czy psychologia szkolna to to samo co psychologia edukacyjna?", "a": "<p>Nie. Psychologia szkolna <strong>nie wyczerpuje</strong> zakresu psychologii edukacyjnej, ale nie ma powodu unikać tego terminu: jest częstym tytułem podręczników anglojęzycznych (Song i in., 2019; Lee, 2005). W Polsce bywa unikany, choć tłumaczenie podręcznika Greena wydano już 50 lat temu.</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["nie", "szkolna nie wyczerpuje zakresu edukacyjnej", "termin częsty w podręcznikach anglojęzycznych"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:456c49b5", "q": "Czym psycholog edukacyjny różni się od psychologa klinicznego dziecka, skoro mają tych samych klientów?", "a": "<p>Kontekstem instytucjonalnym i zadaniami. <strong>Edukacyjny:</strong> placówki edukacyjne (szkoła, poradnia psychologiczno-pedagogiczna), zmiany nieco bardziej zewnętrzne, w strategiach wychowawczych. <strong>Kliniczny:</strong> opieka zdrowotna, zdrowie psychiczne, sytuacja rodzinna; głębsze zmiany emocjonalne i w relacjach w rodzinie. Gdy potrzeby dziecka wykraczają poza kompetencje, psycholog edukacyjny po wstępnym rozpoznaniu <strong>przekierowuje</strong> klienta do klinicznego.</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["kontekst instytucjonalny i zadania", "edukacyjny: placówki, zmiany zewnętrzne", "kliniczny: zdrowie, głębsze zmiany", "przekierowanie do klinicznego"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:7235cee6", "q": "Jaką tezę o relacji do psychologii dziecięcej ryzykuje autorka?", "a": "<p>Że psychologia edukacyjna jest <strong>subdyscypliną psychologii dziecięcej</strong>, bo ma znacznie węższy zakres pracy. W diagnozie dodatkowo specjalizuje się w specjalnych potrzebach edukacyjnych i współpracuje z pedagogami przeprowadzającymi diagnozę.</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["subdyscyplina psychologii dziecięcej", "węższy zakres pracy", "specjalne potrzeby edukacyjne"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:bf88b999", "q": "Jak nazywa się psycholog w Wielkiej Brytanii i USA i jak ma się to do Polski?", "a": "<p><strong>Wielka Brytania:</strong> psycholog edukacyjny, specjalista spoza szkoły, opiekujący się rejonem i kilkoma szkołami, działający po „zgłoszeniu”. <strong>USA:</strong> psycholog szkolny, związany z lokalizacją w szkole, mniej reagujący na zgłoszenia, bardziej proaktywnie współpracujący z placówką. <strong>Polska:</strong> połączenie obu: psycholog rejonowy w poradni (jak w UK) i psycholog szkolny (jak w USA).</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["UK: psycholog edukacyjny spoza szkoły, rejon", "USA: psycholog szkolny w szkole, proaktywny", "Polska: połączenie obu"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:5e3420c4", "q": "Czym pedagogika różni się od psychologii edukacyjnej i gdzie się spotykają?", "a": "<p>Pedagogika to dyscyplina akademicka o odrębnej tradycji: kształtuje wizje edukacji, odpowiada, czym edukacja ma być, określa jej cele i analizuje wyzwania. Stawia podobne pytania o proces edukacji, ale inne metody i narzędzia. W praktyce psycholog współpracuje z pedagogiem szkolnym, terapeutą pedagogicznym, pedagogiem specjalnym i nauczycielem przedmiotowym. Obszar spotkania: <strong>polityka edukacyjna</strong>.</p>", "src": "Dyscypliny pokrewne", "k": ["pedagogika: wizje i cele edukacji", "inne metody i narzędzia", "współpraca z pedagogami i nauczycielami", "polityka edukacyjna"], "u": "wyklad-1.html", "s": "s3"}, {"id": "edukacja/fiszki:a07a98d6", "q": "Czym są studia edukacyjne i jaką analogię stawia autorka?", "a": "<p>Interdyscyplinarne podejście empiryczne, odrębne teoretycznie i metodologicznie od pedagogiki osadzonej w myśli filozoficznej. Analogia: <strong>psychologia edukacyjna ma się do psychologii kształcenia i wychowawczej tak, jak edukacja do studiów edukacyjnych i pedagogiki</strong>; obie są praktycznym zastosowaniem wiedzy z dziedzin podstawowych.</p>", "src": "Dyscypliny pokrewne", "k": ["interdyscyplinarne podejście empiryczne", "odrębne od pedagogiki filozoficznej", "analogia: edukacyjna – kształcenia jak edukacja – studia edukacyjne"], "u": "wyklad-1.html", "s": "s3"}, {"id": "edukacja/fiszki:8d323404", "q": "Dlaczego zdrowie publiczne jest dyscypliną pokrewną psychologii edukacyjnej?", "a": "<p>Zdrowie publiczne to zarazem nauka i działalność publiczna z wyraźnym systemem wartości; zapobiega chorobom i poprawia jakość życia w wymiarze społecznym i środowiskowym, a nie leczy pojedynczych osób. Psychologia edukacyjna podejmuje podobne wyzwania w węższym zakresie: tragiczny stan zdrowia psychicznego dzieci (Sajkowska, 2017; Krokstad, 2021) wymaga intensyfikacji opieki psychologicznej w populacji szkolnej i rozwiązań systemowych.</p>", "src": "Dyscypliny pokrewne", "k": ["nauka i działalność publiczna z systemem wartości", "zapobieganie, nie leczenie jednostek", "zły stan zdrowia psychicznego dzieci", "rozwiązania systemowe"], "u": "wyklad-1.html", "s": "s3"}, {"id": "edukacja/fiszki:94c55298", "q": "Dlaczego psychologia edukacyjna jest „hybrydą” i co znaczy cytat o „najokrutniejszym froncie”?", "a": "<p>Jako dyscyplina aplikacyjna łączy interdyscyplinarnie wiele podejść, teorii i ram konceptualnych, odpowiadając na pilne potrzeby społeczne. Szulevicz i Tanggaard (2017) nazywają ją „jednym z najokrutniejszych frontów współczesnej psychologii”. Ich podręcznik jest ceniony m.in. dlatego, że opisuje stan faktyczny praktyki zamiast narzucać oderwane od realiów teorie.</p>", "src": "Czym jest psychologia edukacyjna", "k": ["łączy wiele podejść i teorii", "odpowiada na pilne potrzeby społeczne", "„najokrutniejszy front” (Szulevicz, Tanggaard)", "opis realnej praktyki"], "u": "wyklad-1.html", "s": "s4"}, {"id": "edukacja/fiszki:de62b986", "q": "Jak Reynolds i Miller (2003) określają zakres psychologii edukacyjnej i jakie wyróżniają działy?", "a": "<p>Zakres: zastosowanie zasad psychologii do badania procesów uczenia się i rozwoju w kontekście systemu edukacji. Pięć działów: (1) poznawcze wyznaczniki uczenia się i rozwoju, (2) procesy socjokulturowe i relacyjne w nauczaniu, (3) realizacja podstawy programowej, (4) nietypowi uczniowie, (5) programy i polityka edukacyjna.</p>", "src": "Czym jest psychologia edukacyjna", "k": ["psychologia w procesach uczenia się i rozwoju w edukacji", "poznawcze wyznaczniki uczenia się", "procesy socjokulturowe i relacyjne", "podstawa programowa", "nietypowi uczniowie; programy i polityka"], "u": "wyklad-1.html", "s": "s4"}, {"id": "edukacja/fiszki:ecb314b7", "q": "Czym różnią się model teoretyczny, ramy konceptualne i ramy praktyczne?", "a": "<p><strong>Model / ramy teoretyczne:</strong> teorie ekspertów jako baza do interpretacji danych empirycznych. <strong>Ramy konceptualne:</strong> termin szerszy, czyli konceptualizacja całości projektu badawczego (temat, problem, pytania, literatura, metodologia, analiza, wnioski), bardziej indywidualna. <strong>Ramy praktyczne (wykonawcze):</strong> seria kroków i etapów stosowania modelu teoretycznego; dotyczą dyscypliny stosowanej i <strong>wypełniają lukę</strong> między modelami a ich skutecznym zastosowaniem.</p>", "src": "Modele teoretyczne i ramy praktyczne", "k": ["model teoretyczny: teorie ekspertów do interpretacji", "ramy konceptualne: konceptualizacja całego projektu", "ramy praktyczne: kroki stosowania modelu"], "u": "wyklad-1.html", "s": "s5"}, {"id": "edukacja/fiszki:c0640471", "q": "Jakie korzyści dają ramy praktyczne i jakie cechy postulują ich twórcy?", "a": "<p><strong>Korzyści:</strong> przejrzysta struktura złożonych problemów, jednoznaczne związki wyników diagnozy z planem interwencji, mniej niepotrzebnych działań diagnostycznych i arbitralnych zaleceń, lepsza jakość usług i satysfakcja praktyków. <strong>Cechy:</strong> transparentność i odpowiedzialność: rama jest znana i akceptowana przez wszystkich uczestników (psychologów, rodziców, ucznia, nauczycieli, placówkę), co służy szacunkowi, podmiotowemu traktowaniu i współpracy.</p>", "src": "Modele teoretyczne i ramy praktyczne", "k": ["przejrzysta struktura problemów", "związek diagnozy z interwencją", "mniej arbitralnych zaleceń", "transparentność i odpowiedzialność"], "u": "wyklad-1.html", "s": "s5"}, {"id": "edukacja/fiszki:7799f905", "q": "Na czym polega podejście pragmatyczne w psychologii edukacyjnej?", "a": "<p>Model, który w interpretacji problemu i szukaniu rozwiązań kieruje się <strong>przewidywaną w danym kontekście skutecznością</strong> zastosowania teorii lub ram. Problem można konceptualizować na wiele sposobów, a więcej niż jedno rozwiązanie może być skuteczne; wybór ma być elastyczny, nie arbitralny, i odwoływać się do zasobów w kontekście. W praktyce po wstępnej konsultacji psycholog decyduje o potrzebach klienta i ścieżce postępowania.</p>", "src": "Podejście pragmatyczne", "k": ["kieruje się przewidywaną skutecznością", "wiele konceptualizacji i rozwiązań", "wybór elastyczny, nie arbitralny", "zasoby w kontekście"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:537016f0", "q": "Co oznacza metafora bricoleura (majsterkowicza) i jaką cechę psychologa podkreślają badania SWPS?", "a": "<p>Majsterkowicz rozwiązuje różne problemy praktyczne dostępnymi środkami, niekoniecznie do tego przeznaczonymi ani doskonałymi, żeby rozwiązać problem skutecznie. Wymaga to kreatywności i otwartości na niestandardowe rozwiązania (Burnham, 2013; Szulevicz i Tanggaard, 2017). W badaniach SWPS (Czeranowska, 2022a) doświadczeni psychologowie wskazują <strong>kreatywność</strong> jako kluczowy przymiot.</p>", "src": "Podejście pragmatyczne", "k": ["rozwiązywanie problemów dostępnymi środkami", "kreatywność i otwartość", "kreatywność kluczowa (SWPS)"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:ae065c2a", "q": "Jakie obszary działania psychologa wymienia rozdział i dlaczego „zgłoszenie” to nie jedyny wariant pracy?", "a": "<p><strong>Diagnoza</strong> dziecka i środowiska (określenie barier, modyfikacja kontekstu), <strong>wsparcie</strong> (psychoedukacja, negocjacje, poradnictwo, elementy terapii, interwencja w kryzysie), <strong>przekierowanie lub współpraca</strong> z innymi specjalistami. Często „sprawą” jest sytuacja (np. przemoc rówieśnicza w klasie), a psycholog może i powinien <strong>proaktywnie</strong> tworzyć optymalne środowisko i prewencję.</p>", "src": "Podejście pragmatyczne", "k": ["diagnoza dziecka i środowiska", "wsparcie (psychoedukacja, poradnictwo, kryzys)", "przekierowanie, współpraca", "„sprawą” bywa sytuacja", "proaktywna prewencja"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:1b058ff0", "q": "Do jakiej refleksji zachęcają Katra i Sokołowska (2010) oraz Wicks (2013)?", "a": "<p><strong>Katra i Sokołowska:</strong> psychologowie szkolni mają się zastanowić, jakie modele i ramy pracy wybierają w realnych sytuacjach i czym się kierują: naturą wyzwania czy własnymi preferencjami. <strong>Wicks:</strong> z pozycji konstruktywizmu społecznego psychologowie mają osobiste opinie o tym, z jakich podejść korzystać, więc powinni zastanowić się, jak ich przekonania, doświadczenia, postawy i przygotowanie zawodowe wpływają na wybory; ramy w praktyce są bardzo zróżnicowane.</p>", "src": "Podejście pragmatyczne", "k": ["jakie modele wybierają i czym się kierują", "natura wyzwania czy własne preferencje", "wpływ przekonań i doświadczeń na wybory (Wicks)"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:1db6d70c", "q": "Jak definiują psychologię edukacji Skinner, Anderson, Stephens i Kolesnik?", "a": "<p><strong>Skinner</strong>: gałąź psychologii o nauczaniu i uczeniu się, obejmująca cechy i zachowania związane z edukacją. <strong>Anderson</strong>: zastosowanie „czystej” psychologii w edukacji, by uspołeczniać jednostkę i modyfikować jej zachowanie. <strong>Stephens</strong>: systematyczne badanie rozwoju edukacyjnego i rozwoju dziecka. <strong>Kolesnik</strong>: bada zjawiska i teorie, które pomagają wyjaśnić i usprawnić edukację. (Peel: nauka o edukacji.)</p>", "src": "Slajdy W1", "k": ["Skinner: nauczanie i uczenie się", "Anderson: zastosowanie psychologii", "Stephens: rozwój edukacyjny", "Kolesnik: wyjaśnić i usprawnić"], "u": "wyklad-1.html", "s": "p1"}, {"id": "edukacja/fiszki:4c2ea347", "q": "Czym różnią się nazwy: psychologia wychowania, rozwojowo-wychowawcza i psychologia edukacji?", "a": "<p><strong>Psychologia wychowania</strong> – badania podstawowe nad procesami kształcenia (Trempała). <strong>Rozwojowo-wychowawcza</strong> – podkreśla, że procesy wychowawcze i rozwojowe są nierozłączne. <strong>Psychologia edukacji</strong> – uwzględnia, że kształcenie trwa całe życie (edukacja ustawiczna), nie kończy się na szkole.</p>", "src": "Slajdy W1", "k": ["wychowania: badania podstawowe", "rozwojowo-wychowawcza: nierozłączność", "edukacji: kształcenie przez całe życie"], "u": "wyklad-1.html", "s": "p1"}, {"id": "edukacja/fiszki:8b9a3818", "q": "Jakie działy psychologii stosowanej składają się na psychologię edukacji i z jakich dziedzin akademickich ona czerpie?", "a": "<p>Stosowana: psychologia <strong>kształcenia i uczenia się, szkolna, pedagogiczna, wychowania</strong>. Akademicka: czerpie z psychologii <strong>poznawczej, społecznej, rozwoju i różnic indywidualnych</strong>.</p>", "src": "Slajdy W1", "k": ["kształcenia i uczenia się, szkolna", "pedagogiczna, wychowania", "poznawcza, społeczna", "rozwoju, różnic indywidualnych"], "u": "wyklad-1.html", "s": "p2"}, {"id": "edukacja/fiszki:79cbaea2", "q": "Kto był pionierem psychologii edukacji na świecie i w Polsce?", "a": "<p>Świat: <strong>William James, John Dewey, Edward L. Thorndike</strong>; badania etniczne – <strong>Mamie Phipps Clark i Kenneth Clark</strong>. Polska: <strong>Aniela Szycówna</strong> i <strong>Jan Władysław Dawid</strong>; „Przegląd Pedagogiczny” (1882), „Polskie Archiwum Psychologii” (1926), Zakład Psychologii Wychowawczej UW (1927/28), Katedra Psychologii Pedagogicznej UJ (1928), „Psychologia Wychowawcza” (1938).</p>", "src": "Slajdy W1", "k": ["James, Dewey, Thorndike", "Clarkowie – badania etniczne", "Szycówna, Dawid", "Przegląd Pedagogiczny 1882"], "u": "wyklad-1.html", "s": "p3"}, {"id": "edukacja/fiszki:3d61cc0f", "q": "Na czym opiera się behawioralne podejście do edukacji i wychowania?", "a": "<p>Stosowana analiza zachowania: dziecko zachowuje się tak, bo ten sposób okazał się w przeszłości <strong>korzystny</strong>. Zachowania niepożądane są <strong>wyuczone</strong>, więc można ich oduczyć. Przyczyny leżą w <strong>środowisku</strong>, które trzeba uwzględnić w modyfikacji. Zachowania kształtuje się przez <strong>wzmocnienia</strong>.</p>", "src": "Slajdy W1", "k": ["zachowanie było korzystne", "wyuczone → można oduczyć", "przyczyny w środowisku", "wzmocnienia"], "u": "wyklad-1.html", "s": "p4"}, {"id": "edukacja/fiszki:a96c1598", "q": "Jakie trzy elementy wiążą teorie społeczno-poznawcze i co zalicza się do czynników wewnętrznych?", "a": "<p><strong>Środowisko, zachowanie i czynniki wewnętrzne</strong> wpływają na siebie nawzajem. Czynniki wewnętrzne to przekonania, oczekiwania, motywacja, cele, wartości i emocje.</p>", "src": "Slajdy W1", "k": ["środowisko", "zachowanie", "czynniki wewnętrzne", "wzajemny wpływ"], "u": "wyklad-1.html", "s": "p4"}, {"id": "edukacja/fiszki:1900d830", "q": "Jakie dwie koncepcje konstruktywistyczne omówiono na wykładzie?", "a": "<p><strong>Poznawczo-rozwojowa</strong>: struktura poznawcza zmienia się dzięki procesom regulacyjnym, zaburzenie równowagi napędza rozwój, a edukacja go stymuluje. <strong>Przetwarzania informacji</strong>: psychika jako układ przetwarzający informacje o ograniczonej pojemności i wydajności; stąd m.in. technologie w nauczaniu.</p>", "src": "Slajdy W1", "k": ["poznawczo-rozwojowa: zaburzenie równowagi", "edukacja stymuluje rozwój", "przetwarzanie informacji", "pojemność i wydajność"], "u": "wyklad-1.html", "s": "p4"}, {"id": "edukacja/fiszki:18a5fe2d", "q": "Czym różnią się badania opisowe, korelacyjne, eksperymentalne i ewaluacyjne w psychologii edukacji?", "a": "<p><strong>Opisowe</strong> rejestrują zachowania i postawy, ale nie mówią o przyczynach. <strong>Korelacyjne</strong> pokazują związek i pozwalają przewidywać, ale nie przyczynowość (permisywność a niska samokontrola). <strong>Eksperymentalne</strong>: losowy przydział do grup, manipulacja zmienną niezależną (np. program zarządzania czasem), pomiar zależnej (oceny). <strong>Ewaluacyjne</strong>: skuteczność programów i ocenianie efektów uczenia się (sprawdzające, różnicujące).</p>", "src": "Slajdy W1", "k": ["opisowe: bez przyczyn", "korelacyjne: związek, nie przyczyna", "eksperyment: losowy przydział", "ewaluacyjne: skuteczność programów"], "u": "wyklad-1.html", "s": "p5"}, {"id": "edukacja/fiszki:329c0757", "q": "Jakie są rodzaje obserwacji i inne metody opisowe w psychologii edukacji?", "a": "<p>Obserwacja <strong>laboratoryjna, w naturalnym środowisku, uczestnicząca</strong> (np. Crowley i in., 2001: rodzice częściej wyjaśniali zjawiska naukowe chłopcom). Inne: wywiady i kwestionariusze, testy, badania psychofizjologiczne, studia przypadków, badania etnograficzne, grupy fokusowe, dzienniki.</p>", "src": "Slajdy W1", "k": ["laboratoryjna, naturalna, uczestnicząca", "wywiady, kwestionariusze, testy", "studia przypadków, etnografia", "fokusy, dzienniki"], "u": "wyklad-1.html", "s": "p5"}, {"id": "edukacja/fiszki:287af86d", "q": "Jaki jest zakres, cel i kluczowe obszary badań psychologii edukacji?", "a": "<p><strong>Zakres</strong>: strona ucznia (uczeń, proces, strategie i sytuacja uczenia się) i nauczyciela (nauczyciel, treść, sposób i sytuacja nauczania, ewaluacja). <strong>Cel</strong>: fakty i metody do rozwiązywania problemów dydaktycznych, postawa naukowa, wykorzystanie psychologii w wychowaniu i edukacji. <strong>Obszary</strong>: procesy poznawcze, emocjonalno-społeczne, różnice indywidualne, uwarunkowania rozwoju i wychowania.</p>", "src": "Slajdy W1", "k": ["strona ucznia i nauczyciela", "fakty i metody, postawa naukowa", "poznawcze, emocjonalno-społeczne", "różnice indywidualne, uwarunkowania"], "u": "wyklad-1.html", "s": "p6"}, {"id": "edukacja/wyklad-1-trusz-fiszki:cccb0cdd", "q": "Czym jest samospełniające się proroctwo w edukacji i dlaczego jest groźne?", "a": "<p>To sytuacja, w której pierwotnie <strong>nietrafne</strong> oczekiwania (za niskie lub za wysokie) rodziców czy nauczycieli, przez ich mniej lub bardziej intencjonalne zachowania, z czasem <strong>stają się rzeczywistością</strong>. Szczególnie groźne u dzieci rzekomo zaburzonych – oczekiwane ograniczenia mogą przejść w realną niepełnosprawność. Nawet mały efekt (r ≈ 0,2) oznacza zmianę u ok. 10% dzieci.</p>", "src": "Trusz (2011)", "k": ["nietrafne oczekiwania", "zachowania dorosłych", "stają się rzeczywistością", "r ≈ 0,2 → ok. 10% dzieci"], "u": "wyklad-1-trusz.html", "s": "s1"}, {"id": "edukacja/wyklad-1-trusz-fiszki:01392418", "q": "Opisz eksperyment Pigmaliona i jego wyniki.", "a": "<p>Rosenthal i Jacobson (Oak School): wszystkich uczniów zbadano testem TOGA, nauczycielom powiedziano, że przewiduje on „rozkwit” intelektualny, i podano nazwiska <strong>losowo wybranych</strong> ok. 20% dzieci. Po 8 miesiącach dzieci z listy miały wyższy przyrost IQ (średnio +3,8 pkt), najsilniej w klasie I (+27,4 vs +12). Nauczyciele oceniali je też jako ciekawsze i szczęśliwsze; paradoksalnie dzieci z grupy kontrolnej, które zyskały na IQ, oceniano gorzej.</p>", "src": "Trusz (2011)", "k": ["losowy wybór „rozkwitających”", "manipulacja oczekiwaniami nauczycieli", "wyższy przyrost IQ, najsilniej w klasie I", "lepsza ocena zachowania; paradoks grupy kontrolnej"], "u": "wyklad-1-trusz.html", "s": "s2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:0ab79ccd", "q": "Jak oceniano wyniki replikacji eksperymentu Pigmaliona?", "a": "<p>Przeprowadzono ok. 500 replikacji. Spitz: na 19 eksperymentów do 1974 r. tylko 3 wykazały wpływ na IQ. Harris i Rosenthal: metaanalizy ponad 400 badań pokazują efekt o znaczeniu praktycznym – przeciętny w warunkach naturalnych, duży w eksperymentach. Brophy: oczekiwania wyjaśniają 3–10% wariancji osiągnięć, a wpływ może trwać latami.</p>", "src": "Trusz (2011)", "k": ["ok. 500 replikacji", "Spitz: mało udanych", "metaanalizy: realny efekt", "3–10% wariancji (Brophy)"], "u": "wyklad-1-trusz.html", "s": "s2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:8081f584", "q": "Czym jest efekt Golema? Omów badanie Rista.", "a": "<p><strong>Efekt Golema</strong> to negatywna odmiana samospełniającego się proroctwa. Rist obserwował klasę, w której nauczycielka po 8 dniach podzieliła dzieci przy stolikach rzekomo według zdolności, a faktycznie według <strong>statusu społeczno-ekonomicznego</strong>. Faworyzowała stolik 1; dzieci z niego kpiły z innych, a dzieci ze stolików 2 i 3 zaczęły nazywać siebie „głupkami”. IQ się nie różniło, ale ucierpiały motywacja i relacje.</p>", "src": "Trusz (2011)", "k": ["negatywna odmiana proroctwa", "podział według SES", "faworyzowanie i wrogość stolika 1", "przejęcie hierarchii przez klasę"], "u": "wyklad-1-trusz.html", "s": "s3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:bb2dc0d5", "q": "Jaką rolę w efekcie oczekiwań odgrywają autooczekiwania dziecka?", "a": "<p>Dziecko dąży do <strong>spójności</strong> zachowania ze schematem „ja”: przy niskiej ocenie siebie działa poniżej możliwości i unika kontaktów (chłopiec z IQ 115–125, przekonany o niskich zdolnościach, osiągnął potem 85–100). Weinstein: osiągnięcia lepiej przewidują oczekiwania nauczyciela razem z autooczekiwaniami i <strong>dostrzeganym faworyzowaniem</strong>. Negatywne oczekiwania mogą prowadzić do wyuczonej bezradności.</p>", "src": "Trusz (2011)", "k": ["spójność z obrazem „ja”", "działanie poniżej możliwości", "dostrzegane faworyzowanie", "wyuczona bezradność"], "u": "wyklad-1-trusz.html", "s": "s3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:9e93959f", "q": "Na czym polega efekt akumulacji oczekiwań? Podaj przykłady badań nad rodzicami.", "a": "<p>Gdy dziecko jest faworyzowane lub defaworyzowane w kilku środowiskach (szkoła i dom), łączna siła efektu rośnie (Jussim i Harber); etykiety mogą się sumować (piętna wielorakie). Englund i in.: oczekiwania matek zwiększały ich zaangażowanie w edukację, ale raczej wyniki dziecka wpływały na oczekiwania. Madon i in.: picie alkoholu przez dzieci najlepiej przewidywało przeszacowanie przez <strong>oboje</strong> rodziców – akumulacja dotyczyła tylko oczekiwań negatywnych.</p>", "src": "Trusz (2011)", "k": ["kumulacja wpływów z kilku środowisk", "piętna wielorakie", "Englund – zaangażowanie matek", "Madon – alkohol, tylko negatywne"], "u": "wyklad-1-trusz.html", "s": "s4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:c4ca36e6", "q": "Jakie cztery czynniki pośredniczą w komunikowaniu oczekiwań (Rosenthal)?", "a": "<p><strong>Klimat</strong> – więcej wsparcia emocjonalnego; <strong>sprzężenia zwrotne</strong> – więcej trafnych informacji zwrotnych i pochwał; <strong>wkład</strong> – więcej i trudniejszego materiału; <strong>wydajność</strong> – więcej okazji do pokazania wiedzy. Wszystkie wiążą się z osiągnięciami (Harris i Rosenthal), najsilniej klimat i wkład.</p>", "src": "Trusz (2011)", "k": ["klimat", "sprzężenia zwrotne", "wkład", "wydajność"], "u": "wyklad-1-trusz.html", "s": "s5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:72e8eed7", "q": "Jakie reguły pomagają ograniczyć negatywny efekt oczekiwań?", "a": "<p>Szukać informacji o <strong>zachowaniach</strong> dziecka w różnych sytuacjach; <strong>zawieszać ocenę</strong>; informacje wieloznaczne interpretować na korzyść dziecka; pokazywać, że zdolności zależą od <strong>wysiłku</strong>; porażki przypisywać chwilowemu brakowi zaangażowania, a sukcesy zdolnościom; angażować wszystkie dzieci; dawać konstruktywne informacje zwrotne.</p>", "src": "Trusz (2011)", "k": ["obserwacja zachowań", "zawieszanie oceny", "interpretacja na korzyść", "zdolności zależą od wysiłku", "angażowanie i konstruktywne informacje zwrotne"], "u": "wyklad-1-trusz.html", "s": "s5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:73fb25b0", "q": "Czym różni się efekt autooczekiwań od efektu oczekiwań interpersonalnych?", "a": "<p><strong>Autooczekiwania</strong> to oczekiwania wobec siebie, które utrudniają lub ułatwiają osiągnięcie celu (samoutrudnianie, placebo). <strong>Oczekiwania interpersonalne</strong> to oczekiwania jednej osoby wobec zachowania innej, które doprowadzają do pojawienia się tego zachowania – działają jak samospełniające się proroctwo.</p>", "src": "Slajdy W2", "k": ["autooczekiwania: wobec siebie", "samoutrudnianie, placebo", "interpersonalne: wobec innej osoby", "samospełniające się proroctwo"], "u": "wyklad-1-trusz.html", "s": "p1"}, {"id": "edukacja/wyklad-1-trusz-fiszki:a868514d", "q": "Jakie są trzy etapy samospełniającego się proroctwa i dwa poziomy potwierdzenia oczekiwań?", "a": "<p>Etapy: <strong>indukcja</strong> oczekiwań, <strong>mediacja (komunikacja)</strong> oczekiwań, <strong>behawioralne potwierdzenie</strong>. Potwierdzenie może być <strong>rzeczywiste</strong> (osoba naprawdę zmienia zachowanie) albo <strong>percepcyjne</strong> (obserwator widzi to, czego oczekiwał).</p>", "src": "Slajdy W2", "k": ["indukcja", "komunikacja", "potwierdzenie", "rzeczywiste vs percepcyjne"], "u": "wyklad-1-trusz.html", "s": "p1"}, {"id": "edukacja/wyklad-1-trusz-fiszki:122e2bc8", "q": "Czym różni się efekt Galatei od efektu Golema?", "a": "<p>Oba są odmianami efektu Pigmaliona. <strong>Galatea</strong>: wysokie oczekiwania nauczyciela bezpośrednio podnoszą kompetencje intelektualne i motywację ucznia. <strong>Golem</strong>: niskie oczekiwania obniżają kompetencje i motywację.</p>", "src": "Slajdy W2", "k": ["Galatea: wysokie oczekiwania → wzrost", "Golem: niskie oczekiwania → spadek", "kompetencje i motywacja"], "u": "wyklad-1-trusz.html", "s": "p2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:f854fd6b", "q": "Co pokazały badania Trouilloud i in. (2006) oraz Szumskiego i Karwowskiego (2019)?", "a": "<p><strong>Trouilloud</strong> (WF, 421 uczniów): wczesne oczekiwania nauczycieli wiązały się z późniejszą postrzeganą kompetencją, zwłaszcza pozytywne, i silniej przy niskim wspieraniu autonomii. <strong>Szumski i Karwowski</strong> (matematyka, 1488 uczniów 13–15 lat): efekt działa też u starszych uczniów, indywidualnie i grupowo; niski SES klasy i liczba uczniów z problemami wiążą się z negatywnymi oczekiwaniami.</p>", "src": "Slajdy W2", "k": ["efekt poza poznaniem (WF)", "silniej przy niskiej autonomii", "także u nastolatków", "poziom indywidualny i grupowy"], "u": "wyklad-1-trusz.html", "s": "p2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:93f45055", "q": "Na czym polega pryzmat starszego rodzeństwa (Seaver, 1973)?", "a": "<p>Oczekiwania nauczyciela wobec młodszego dziecka powstają na podstawie doświadczeń ze starszym rodzeństwem. Gdy uczy <strong>ten sam nauczyciel</strong>: dobre starsze rodzeństwo → efekt Galatei, słabe → efekt Golema. Przy <strong>innym nauczycielu</strong> efektu brak.</p>", "src": "Slajdy W2", "k": ["oczekiwania przez starsze rodzeństwo", "ten sam nauczyciel: Galatea lub Golem", "inny nauczyciel: brak efektu"], "u": "wyklad-1-trusz.html", "s": "p2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:21621120", "q": "Jakie klasy zmiennych wyróżnia model Rosenthala?", "a": "<p><strong>A</strong> – dalsze (moderator) i <strong>B</strong> – bliższe (oczekiwania): zmienne niezależne. <strong>C</strong> – zachowania osoby mającej oczekiwania: proces pośredniczenia. <strong>D</strong> – bliższe (bezpośrednie) i <strong>E</strong> – dalsze (długoterminowe) wyniki: zmienne zależne.</p>", "src": "Slajdy W2", "k": ["A moderator, B oczekiwania", "C zachowanie nauczyciela", "D skutki bezpośrednie", "E skutki długoterminowe"], "u": "wyklad-1-trusz.html", "s": "p3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:8bed81bb", "q": "Skąd biorą się oczekiwania nauczycieli wobec uczniów?", "a": "<p>Z informacji uzyskanych <strong>przed pierwszym kontaktem</strong> (schematy poznawcze, stereotypy społeczne), z <strong>powierzchownych cech</strong> dziecka oraz z <strong>pierwszych obserwacji</strong> jego zachowań w szkole.</p>", "src": "Slajdy W2", "k": ["schematy i stereotypy przed kontaktem", "powierzchowne cechy", "pierwsze obserwacje"], "u": "wyklad-1-trusz.html", "s": "p3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:af2f11b2", "q": "Czym są moderatory edukacyjnego proroctwa i jakie omówiono?", "a": "<p>To czynniki decydujące o <strong>kierunku i sile</strong> wpływu oczekiwań na zachowania i osiągnięcia; działają na etapie indukcji, komunikowania i potwierdzania. Omówiono: prywatne teorie inteligencji, schematy „ja” i poczucie wartości uczniów, atrybucje nauczycieli i uczniów, spostrzegane podobieństwo nauczyciela do ucznia, cechy nauczycieli.</p>", "src": "Slajdy W2", "k": ["kierunek i siła wpływu", "trzy etapy", "teorie inteligencji, schematy „ja”", "atrybucje, podobieństwo, cechy nauczyciela"], "u": "wyklad-1-trusz.html", "s": "p4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:10925fca", "q": "Jak prywatne teorie inteligencji nauczycieli wpływają na ich oczekiwania?", "a": "<p>Nauczyciel, który uważa inteligencję za <strong>cechę stabilną</strong>, ma <strong>sztywne</strong> oczekiwania. Ten, który uważa zdolności za <strong>zmienne</strong>, ma oczekiwania <strong>elastyczne</strong>. Prywatne teorie inteligencji uczniów też wpływają na ich zachowanie.</p>", "src": "Slajdy W2", "k": ["stabilna → sztywne oczekiwania", "zmienna → elastyczne", "teorie uczniów też działają"], "u": "wyklad-1-trusz.html", "s": "p4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:309a10a2", "q": "Którzy nauczyciele są najbardziej podatni na nietrafne oczekiwania?", "a": "<p>Ci o <strong>wysokim dogmatyzmie i autorytaryzmie</strong> oraz <strong>niskiej tolerancji niejednoznaczności</strong>. Podatność spada wraz z <strong>doświadczeniem</strong>, ale rośnie przy <strong>wypaleniu zawodowym</strong>.</p>", "src": "Slajdy W2", "k": ["dogmatyzm, autorytaryzm", "niska tolerancja niejednoznaczności", "doświadczenie zmniejsza", "wypalenie zwiększa"], "u": "wyklad-1-trusz.html", "s": "p4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:5ded4577", "q": "Jak różnią się sprzężenia zwrotne wobec uczniów z wysokimi i niskimi oczekiwaniami?", "a": "<p>Uczniowie z <strong>wysokimi</strong> oczekiwaniami dostają więcej pozytywnych i <strong>adekwatnych</strong> informacji zwrotnych, ale są też częściej karani za zachowania niezgodne z oczekiwaniami. Uczniowie z <strong>niskimi</strong> dostają więcej negatywnych i <strong>nieadekwatnych</strong> (pozytywnych i negatywnych).</p>", "src": "Slajdy W2", "k": ["wysokie: więcej pozytywnych, adekwatnych", "wysokie: częściej karani za odstępstwa", "niskie: więcej negatywnych", "niskie: nieadekwatne"], "u": "wyklad-1-trusz.html", "s": "p5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:d8b2ffd9", "q": "Czym są czynniki „wydajność” i „wkład” w teorii czterech czynników?", "a": "<p><strong>Wydajność</strong>: stopień, w jakim nauczyciel daje uczniowi okazję do działania i wypowiedzi – dłużej czeka na dobrą odpowiedź i częściej wchodzi w interakcję z dziećmi o wysokich oczekiwaniach. <strong>Wkład</strong>: więcej i trudniejszego materiału oraz dodatkowy czas dla wybranych uczniów.</p>", "src": "Slajdy W2", "k": ["wydajność: okazje do wypowiedzi", "dłuższe, częstsze interakcje", "wkład: więcej trudniejszego materiału", "dodatkowy czas"], "u": "wyklad-1-trusz.html", "s": "p5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:19bc9a37", "q": "Jakie wnioski dla praktyki płyną z badań nad efektem oczekiwań?", "a": "<p>Efekt słabo wpływa na samo IQ, ale nie wolno go ignorować. Nauczyciel powinien znać wpływ swoich oczekiwań, budować je na <strong>różnych źródłach</strong>, być <strong>otwarty</strong> na informacje sprzeczne i szukać <strong>pozytywnych</strong> oczekiwań wobec każdego ucznia.</p>", "src": "Slajdy W2", "k": ["nie ignorować mimo małego wpływu na IQ", "świadomość własnych oczekiwań", "różne źródła, otwartość", "pozytywne oczekiwania wobec każdego"], "u": "wyklad-1-trusz.html", "s": "p6"}, {"id": "edukacja/wyklad-2-fiszki:48e45f63", "q": "Porównaj podejścia do inteligencji: czynnik ogólny i wiele zdolności.", "a": "<p><strong>Czynnik ogólny</strong>: Spearman – g i zdolności specyficzne s; Cattell – inteligencja płynna (Gf, wrodzona, operacje na symbolach) i skrystalizowana (Gc, wiedza nabyta). <strong>Wiele zdolności</strong>: Guilford – 180 zdolności (treści × operacje × produkty), myślenie konwergencyjne vs dywergencyjne; Gardner – 7 niezależnych inteligencji; Sternberg – teoria triarchiczna.</p>", "src": "Ledzińska i Czerniawska", "k": ["Spearman g i s", "Cattell Gf i Gc", "Guilford 180, konwergencyjne/dywergencyjne", "Gardner – wielorakie"], "u": "wyklad-2.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:5999455f", "q": "Wymień inteligencje wielorakie Gardnera i znaczenie tej teorii dla szkoły.", "a": "<p>Logiczno-matematyczna, językowa, muzyczna, przestrzenna, cielesno-kinestetyczna, interpersonalna, intrapersonalna. Gardner krytykuje dominację inteligencji akademickiej (werbalnej i logiczno-matematycznej) w szkole; uznaje, że każda inteligencja zależy od wrodzonych właściwości i środowiska, więc <strong>każdą można rozwijać</strong>.</p>", "src": "Ledzińska i Czerniawska", "k": ["7 inteligencji", "krytyka inteligencji akademickiej", "niezależność inteligencji", "każdą można rozwijać"], "u": "wyklad-2.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:ea46138b", "q": "Jaki jest związek inteligencji z osiągnięciami szkolnymi?", "a": "<p>Korelacje IQ z ocenami są <strong>słabe, ale dodatnie i istotne</strong>, i maleją z poziomem kształcenia; IQ wyjaśnia ok. 25–30% wariancji wyników. Kierunek jest sporny (Sternberg – szybsza automatyzacja; Ackerman – rola na początku nabywania umiejętności). Mimo to żaden inny czynnik nie wyjaśnia więcej, a inteligencję można rozwijać w szkole.</p>", "src": "Ledzińska i Czerniawska", "k": ["słabe, istotne korelacje", "maleją z poziomem kształcenia", "25–30% wariancji", "sporny kierunek zależności"], "u": "wyklad-2.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:ccb52ede", "q": "Na czym polega koncepcja inteligencji sprzyjającej powodzeniu życiowemu Sternberga?", "a": "<p>Inteligencja to zdolność osiągania sukcesu według <strong>osobistych standardów</strong> w danym kontekście. Składa się z trzech względnie niezależnych inteligencji: <strong>analitycznej</strong> (akademickiej, mierzonej IQ), <strong>twórczej</strong> (nowe problemy i idee) i <strong>praktycznej</strong> (zdrowy rozsądek, przystosowanie i kształtowanie otoczenia). Sukces wymaga ich harmonizacji, wykorzystania mocnych i kompensowania słabych stron.</p>", "src": "Ledzińska i Czerniawska", "k": ["sukces wg osobistych standardów", "analityczna", "twórcza", "praktyczna", "harmonizacja"], "u": "wyklad-2.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:84e87e14", "q": "Scharakteryzuj wymiar refleksyjność–impulsywność i jego znaczenie dla uczenia się.", "a": "<p>Kagan: indywidualna tendencja w sytuacjach z kilkoma możliwymi rozwiązaniami. <strong>Impulsywni</strong> odpowiadają szybko, popełniają więcej błędów (losowych), lepiej zapamiętują mimowolnie i radzą sobie w zadaniach na czas i dywergencyjnych. <strong>Refleksyjni</strong> działają wolniej, popełniają mniej błędów, mają lepszą koncentrację, transfer i wyniki w zadaniach konwergencyjnych (początek nauki, przedmioty ścisłe). Wpływ jest silniejszy u młodszych; nauczyciele wyżej oceniają uczniów o podobnym stylu.</p>", "src": "Ledzińska i Czerniawska", "k": ["Kagan, niepewność rozwiązań", "impulsywni: szybko, błędy losowe", "refleksyjni: wolno, mniej błędów", "zadania konwergencyjne vs dywergencyjne", "zgodność stylu z nauczycielem"], "u": "wyklad-2.html", "s": "s2"}, {"id": "edukacja/wyklad-2-fiszki:d2d5e0fb", "q": "Czym jest zależność–niezależność od pola i jak wiąże się z osiągnięciami?", "a": "<p>Witkin: stopień, w jakim spostrzeganie zależy od ogólnej organizacji pola. <strong>Niezależni</strong> (analityczni) wyodrębniają elementy i są odporni na kontekst; <strong>zależni</strong> (globalni) – trudno oddzielają części od całości, są wrażliwi na informacje społeczne. Niezależni lepiej organizują informacje, stosują więcej strategii i zwykle mają lepsze oceny, zwłaszcza z matematyki i przyrody; zależni wolą nauki humanistyczne i zawody społeczne.</p>", "src": "Ledzińska i Czerniawska", "k": ["Witkin", "niezależni – analityczni", "zależni – globalni, społeczni", "przewaga niezależnych w ocenach"], "u": "wyklad-2.html", "s": "s2"}, {"id": "edukacja/wyklad-2-fiszki:37a2a0be", "q": "Opisz style myślenia Sternberga.", "a": "<p>„Zarządzanie umysłem” na wzór rządów: 13 stylów w 5 wymiarach (funkcje, formy, poziomy, zakres, skłonności). <strong>Typ I</strong> – kreatywne, złożone (legislacyjny, sądowniczy, hierarchiczny, globalny, liberalny); <strong>typ II</strong> – cenienie norm (wykonawczy, lokalny, monarchiczny, konserwatywny); <strong>typ III</strong> – zależnie od zadania (anarchiczny, oligarchiczny, wewnętrzny, zewnętrzny).</p>", "src": "Ledzińska i Czerniawska", "k": ["zarządzanie umysłem, 13 stylów", "typ I – kreatywne", "typ II – normatywne", "typ III – zależne od zadania"], "u": "wyklad-2.html", "s": "s2"}, {"id": "edukacja/wyklad-2-fiszki:8d913de8", "q": "Jak cechy Wielkiej Piątki wiążą się z osiągnięciami edukacyjnymi?", "a": "<p><strong>Sumienność</strong> – najsilniejszy predyktor na każdym poziomie. <strong>Ugodowość</strong> – najsłabsza, niespójne wyniki. <strong>Neurotyczność</strong> – negatywna, coraz silniej na wyższych poziomach. <strong>Otwartość</strong> – pozytywna, rosnąca z poziomem kształcenia. <strong>Ekstrawersja</strong> – plus u młodszych, minus u młodzieży; zależy od metody (odkrywcza vs podająca). Wpływ jest głównie pośredni – przez motywację i strategie.</p>", "src": "Ledzińska i Czerniawska", "k": ["sumienność najsilniejsza", "neurotyczność negatywna, rośnie", "otwartość pozytywna", "ekstrawersja zależna od wieku i metody", "wpływ pośredni"], "u": "wyklad-2.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:1bd1a485", "q": "Jakie style uczenia się wiążą się z cechami osobowości?", "a": "<p>Styl <strong>głęboki</strong> (zrozumienie) – z otwartością (i ekstrawersją); <strong>powierzchniowy</strong> (na pamięć) – z neurotycznością i ugodowością; <strong>strategiczny</strong> (maksymalizacja wyników) – z sumiennością i ekstrawersją, ujemnie z neurotycznością. Cechy wyjaśniają 22,7–43,6% wariancji stylów (Duff i in.).</p>", "src": "Ledzińska i Czerniawska", "k": ["głęboki – otwartość", "powierzchniowy – neurotyczność", "strategiczny – sumienność", "22,7–43,6% wariancji"], "u": "wyklad-2.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:a280ea12", "q": "Jak ekstrawertycy i introwertycy różnią się w uczeniu się według Eysencka?", "a": "<p>Ekstrawertycy mają <strong>niższe pobudzenie korowe</strong> i szukają stymulacji; introwertycy – wyższe. W szkole podstawowej ekstrawertycy radzą sobie równie dobrze lub lepiej, w średniej i wyższej – introwertycy. Ekstrawertykom służy uczenie przez odkrywanie, introwertykom metoda podająca. Introwertycy mają lepszą pamięć długotrwałą, ekstrawertycy krótkotrwałą. Neurotycznym i introwertykom służą metody ustrukturalizowane.</p>", "src": "Ledzińska i Czerniawska", "k": ["pobudzenie korowe", "zależność od etapu kształcenia", "odkrywanie vs podająca", "pamięć długotrwała vs krótkotrwała"], "u": "wyklad-2.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:b6dfae54", "q": "Jaki jest związek temperamentu z osiągnięciami szkolnymi?", "a": "<p>Wyniki są niespójne, ale: wytrwałość sprzyja, a aktywność i roztargnienie szkodzą (koncentracja na zadaniu); temperament wyjaśnia ok. 20% wariancji osiągnięć w szkole średniej. Lewowicki: siła pobudzenia i hamowania oraz ruchliwość procesów nerwowych sprzyjają osiągnięciom. Sprzyjają też wytrzymałość i żwawość, szkodzi reaktywność.</p>", "src": "Ledzińska i Czerniawska", "k": ["wytrwałość +, roztargnienie −", "ok. 20% wariancji", "siła i ruchliwość procesów nerwowych", "reaktywność szkodzi"], "u": "wyklad-2.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:a10c6f42", "q": "Jakie są argumenty za indywidualizacją nauczania i jakie są jej formy?", "a": "<p>Argumenty: rozwój potencjału każdego ucznia; różnice w zdolnościach, stylach, osobowości, tempie, wiedzy wyjściowej, wsparciu domu i motywacji; bez indywidualizacji słabsi nie nadążają, a zdolni tracą motywację. Formy: <strong>grupy mieszane</strong> z różnicowaniem treści i tempa (diagnoza, monitorowanie) oraz <strong>grupy jednorodne</strong> (selekcja) – łatwiejsze dla nauczyciela, ale słabsi tracą wzorce. Dawanie najsłabszym tylko prostych zadań utrwala niskie osiągnięcia.</p>", "src": "Ledzińska i Czerniawska", "k": ["różnice między uczniami", "grupy mieszane – różnicowanie", "grupy jednorodne – selekcja", "ryzyko utrwalania niskich osiągnięć"], "u": "wyklad-2.html", "s": "s4"}, {"id": "edukacja/wyklad-2-fiszki:c8e86096", "q": "Czym są strategie uczenia się i jak dzieli je Grupa z Michigan?", "a": "<p>Strategie to świadome sposoby organizowania sytuacji w celu zapamiętania i wykorzystania informacji (Czerniawska). Grupa z Michigan: strategie <strong>poznawcze</strong> (przetwarzanie materiału: powtarzanie, elaboracja, organizowanie), <strong>metapoznawcze</strong> (kierowanie stosowaniem strategii) i <strong>zarządzania zasobami</strong> (warunki zewnętrzne i wewnętrzne).</p>", "src": "Ledzińska i Czerniawska", "k": ["świadome sposoby zapamiętywania", "poznawcze", "metapoznawcze", "zarządzania zasobami"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:5b5a3bcb", "q": "Porównaj strategie powtarzania, elaboracji i organizowania.", "a": "<p><strong>Powtarzanie</strong> – recytowanie, przepisywanie, podkreślanie; niskie zaangażowanie, przydatne na wstępie i do utrwalenia. <strong>Elaboracja</strong> – mnemotechniki, wyobrażenia, opis własnymi słowami, streszczanie; dodaje elementy wspierające pamięć. <strong>Organizowanie</strong> – grupowanie, plany, mapy pojęciowe; wymaga największej aktywności i jest najskuteczniejsze w nauce szkolnej i akademickiej.</p>", "src": "Ledzińska i Czerniawska", "k": ["powtarzanie – płytkie", "elaboracja – opracowanie", "organizowanie – najgłębsze, najskuteczniejsze", "przykłady każdej"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:420af2e5", "q": "Wymień kryteria opisu strategii poznawczych.", "a": "<p>Faza pamięci (zapamiętywanie, przypominanie), poziom aktywności (<strong>głębokie vs powierzchniowe</strong> – najważniejszy), zakres (ogólne vs specyficzne), ukierunkowanie (wewnętrzne vs zewnętrzne), rodzaj działań (werbalne vs niewerbalne), złożoność (proste vs złożone programy, np. SQ3R), naturalność (naturalne vs sztuczne), racjonalność (racjonalne vs magiczne).</p>", "src": "Ledzińska i Czerniawska", "k": ["faza pamięci", "głębokie vs powierzchniowe", "wewnętrzne vs zewnętrzne", "werbalne vs obrazowe", "naturalne/sztuczne, racjonalne/magiczne"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:ca3330f5", "q": "Na czym polega program SQ3R?", "a": "<p>Złożony program uczenia się z tekstu: <strong>Survey</strong> – pobieżny przegląd, struktura; <strong>Question</strong> – stawianie pytań; <strong>Read</strong> – aktywne czytanie w poszukiwaniu odpowiedzi; <strong>Recite</strong> – powtarzanie najważniejszych informacji; <strong>Review</strong> – sprawdzenie, czy wszystko zrozumiane. Polski odpowiednik: 2PSPS (przejrzyj, pytaj, szukaj odpowiedzi, powtarzaj, sprawdź).</p>", "src": "Ledzińska i Czerniawska", "k": ["Survey – przegląd", "Question – pytania", "Read – aktywne czytanie", "Recite i Review – powtórz i sprawdź"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:19835e67", "q": "Jak zmienia się aktywność strategiczna z wiekiem?", "a": "<p>Liczba strategii rośnie do ok. <strong>12–15 r.ż.</strong>, potem maleje; rośnie udział strategii głębokich, wewnętrznych, złożonych i specyficznych, a maleje powierzchniowych, zewnętrznych, prostych, ogólnych i magicznych; poprawia się dopasowanie strategii do zadań oraz monitorowanie i kontrola. Rozwój zmierza do <strong>samoregulacji</strong>.</p>", "src": "Ledzińska i Czerniawska", "k": ["szczyt 12–15 lat", "więcej głębokich i wewnętrznych", "lepsze dopasowanie do zadań", "samoregulacja"], "u": "wyklad-2.html", "s": "s6"}, {"id": "edukacja/wyklad-2-fiszki:f16e5a9a", "q": "Jak notowanie może pełnić funkcję różnych strategii i jak uczyć notowania?", "a": "<p>Notatki <strong>dosłowne</strong> – strategia powtarzania (najmniej skuteczna); <strong>własnymi słowami</strong> z elementami graficznymi – elaboracja; <strong>mapy pojęciowe, notatki macierzowe, drzewka</strong> – organizowanie (najcenniejsze). Uczyć: pokazać różne sposoby, zachęcić do wypróbowania i oceny, nie narzucać stylu; mapy wymagają wprawy.</p>", "src": "Ledzińska i Czerniawska", "k": ["dosłowne – powtarzanie", "własnymi słowami – elaboracja", "mapy i macierze – organizowanie", "nie narzucać stylu"], "u": "wyklad-2.html", "s": "s6"}, {"id": "edukacja/wyklad-2-fiszki:e895d2bf", "q": "Jakie zasady obowiązują przy ćwiczeniu strategii poznawczych z uczniami?", "a": "<p>Systematyczność z wydłużanymi przerwami; krótka rozgrzewka (5–10 min) dopasowana do materiału; podanie celu i przypomnienie wiedzy; od zadań prostych do złożonych; omówienie sesji (gdzie stosować, co trudne, co zmienić); relaks; zachęta do ćwiczenia poza sesjami (dzienniczek strategii); pozytywna informacja zwrotna, a negatywna od razu ze wskazówką poprawy.</p>", "src": "Ledzińska i Czerniawska", "k": ["systematyczność", "rozgrzewka i cel", "od prostych do złożonych", "omówienie i relaks", "informacja zwrotna"], "u": "wyklad-2.html", "s": "s6"}, {"id": "edukacja/wyklad-2-fiszki:38d823ab", "q": "Czym jest funkcja promocyjna psychologa szkolnego i czym różni się od profilaktyki i interwencji?", "a": "<p>W modelu Katry psycholog pełni funkcje monitoringu, psychoprofilaktyki, interwencji i <strong>promocji</strong>. Profilaktyka i interwencja działają „poniżej zera” – usuwają problemy i doprowadzają do normy. Promocja (Jurkowski; łac. <em>promovere</em>) wspiera rozwój <strong>powyżej zera</strong>: to, co dobre, ma stać się lepsze; obejmuje całą osobę i cały bieg życia, twórczość, transgresję (Kozielecki), także u uczniów zdolnych i „trudnych”.</p>", "src": "Budziszewska", "k": ["cztery funkcje (Katra)", "profilaktyka i interwencja – poniżej zera", "promocja – rozwój powyżej normy", "cała osoba, bieg życia, transgresja"], "u": "wyklad-2.html", "s": "s7"}, {"id": "edukacja/wyklad-2-fiszki:4c99c4e8", "q": "Jakie kryteria dojrzałej osobowości mogą wyznaczać cele promocyjne?", "a": "<p><strong>Allport</strong>: samowiedza i refleksja, zainteresowania poza „ja”, dystans i poczucie humoru, własny system wartości, głęboki kontakt z innymi, praktyczne umiejętności, zaangażowanie w dobro wspólne. <strong>Adler</strong>: poczucie wspólnoty. <strong>Maslow</strong>: adekwatna percepcja, szacunek, autentyczność, krytycyzm wobec kultury. Współcześnie: <strong>podmiotowość</strong> (wolność od i do), kreatywność, samoregulacja, aktywność prospektywna.</p>", "src": "Budziszewska", "k": ["Allport – dojrzała osobowość", "Adler – poczucie wspólnoty", "Maslow – samorealizacja", "podmiotowość, samoregulacja"], "u": "wyklad-2.html", "s": "s7"}, {"id": "edukacja/wyklad-2-fiszki:cfb67bdd", "q": "Jakimi sposobami psycholog szkolny może realizować funkcję promocyjną?", "a": "<p><strong>Kształtowanie środowiska i budzenie świadomości</strong> pozaintelektualnych aspektów rozwoju (rozmowy, rady pedagogiczne, perspektywa całego życia, spotkania z ciekawymi ludźmi); <strong>rozwijanie kompetencji emocjonalnych i interpersonalnych</strong> (nazywanie emocji, empatia, asertywność, decentracja wg Selmana); <strong>dopasowanie doświadczeń szkolnych do etapów rozwoju</strong> (Erikson: kompetencja, tożsamość, intymność); <strong>dbałość o własny rozwój</strong> i modelowanie postaw.</p>", "src": "Budziszewska", "k": ["środowisko i świadomość – rzecznik rozwoju", "kompetencje emocjonalne i interpersonalne", "etapy Eriksona", "dbałość o siebie"], "u": "wyklad-2.html", "s": "s7"}, {"id": "edukacja/wyklad-2-fiszki:2c6e6aa1", "q": "Czym różnią się empiryczne i teoretyczne definicje uczenia się?", "a": "<p><strong>Empiryczne</strong> wiążą uczenie się z obserwowalnymi wydarzeniami – np. Guthrie: zmiany w zachowaniu, które następują jako rezultat zachowania. <strong>Teoretyczne</strong> wskazują mechanizmy: fizjologiczne, poznawcze albo traktują uczenie się jako modyfikację zachowania.</p>", "src": "Slajdy W3", "k": ["empiryczne: obserwowalne zdarzenia", "Guthrie", "teoretyczne: mechanizmy", "fizjologiczne, poznawcze, modyfikacja zachowania"], "u": "wyklad-2.html", "s": "p1"}, {"id": "edukacja/wyklad-2-fiszki:12c60452", "q": "Jak definiują uczenie się Hilgard i Marquis, Włodarski oraz J.R. Anderson?", "a": "<p><strong>Hilgard i Marquis</strong>: stosunkowo trwała zmiana w zachowaniu w rezultacie wzmacnianego ćwiczenia. <strong>Włodarski</strong>: zmiany niezależne wyłącznie od receptorów i efektorów, na podłożu indywidualnego doświadczenia; jeśli nietrwałe – zawsze z nowymi elementami. <strong>Anderson</strong>: względnie trwała zmiana w potencjale zachowaniowym – nowa wiedza, umiejętności, postawy. (Woodworth: zdobywanie nowej wiedzy i sposobów reagowania.)</p>", "src": "Slajdy W3", "k": ["Hilgard i Marquis: wzmacniane ćwiczenie", "Włodarski: indywidualne doświadczenie", "Anderson: potencjał zachowaniowy", "wiedza, umiejętności, postawy"], "u": "wyklad-2.html", "s": "p1"}, {"id": "edukacja/wyklad-2-fiszki:472941eb", "q": "Jak rozwija się uczenie się u ludzi i jakie są trzy warunki skutecznego uczenia się?", "a": "<p>Rozwój: warunkowanie → naśladowanie → uczenie się „szkolne” → samodzielne uczenie się i samokształcenie. Warunki: <strong>chcieć, potrafić, wysilić się</strong>. Skuteczne uczenie się to dokładne zapamiętanie, trwałe przechowanie i szybkie przypomnienie w niezmienionej postaci.</p>", "src": "Slajdy W3", "k": ["warunkowanie → naśladowanie", "szkolne → samokształcenie", "chcieć, potrafić, wysilić się", "zapamiętanie, przechowanie, przypomnienie"], "u": "wyklad-2.html", "s": "p2"}, {"id": "edukacja/wyklad-2-fiszki:2d15ca9b", "q": "Jak bywa rozumiany „styl uczenia się” i jakie typy opisuje popularny model?", "a": "<p>Jako preferowany <strong>kanał zmysłowy</strong>, jako <strong>aktywność</strong> podczas uczenia się albo jako <strong>przekonanie</strong> o preferowanym zmyśle. Popularny model: <strong>wzrokowiec</strong> (obrazy, diagramy, czytanie), <strong>słuchowiec</strong> (wykłady, dyskusje, ustne instrukcje), <strong>kinestetyk</strong> (ruch, działanie, manipulowanie).</p>", "src": "Slajdy W3", "k": ["kanał zmysłowy", "aktywność", "przekonanie", "wzrokowy, słuchowy, kinestetyczny"], "u": "wyklad-2.html", "s": "p3"}, {"id": "edukacja/wyklad-2-fiszki:8f182558", "q": "Dlaczego style uczenia się uznano na wykładzie za mit?", "a": "<p>Rzekome podstawy (dominacja półkulowa, Jung, Sternberg) <strong>nie uzasadniają</strong> stylów. Diagnoza opiera się na samoopisie, a narzędzia są <strong>nierzetelne</strong>. Dane o tym, że dopasowanie nauczania do stylu poprawia wyniki, są <strong>niewiarygodne</strong>. Zmysły współpracują (kiki–buba, podwójne kodowanie), więc zamiast stylów warto uczyć <strong>strategii</strong>.</p>", "src": "Slajdy W3", "k": ["brak podstaw teoretycznych", "nierzetelne narzędzia", "brak dowodów na dopasowanie", "zamiast stylów: strategie"], "u": "wyklad-2.html", "s": "p3"}, {"id": "edukacja/wyklad-2-fiszki:26ec57a6", "q": "Na czym polegają podwójne kodowanie i poziomy przetwarzania?", "a": "<p><strong>Podwójne kodowanie</strong>: informacje wzrokowe się werbalizuje, a werbalne wizualizuje – słowo z obrazem zapamiętuje się lepiej. <strong>Poziomy przetwarzania</strong> (Craik i Lockhart, 1972): fizyczny (najpłytszy), fonetyczny, semantyczny (najgłębszy) – im głębsze przetwarzanie, tym trwalsza pamięć.</p>", "src": "Slajdy W3", "k": ["werbalizowanie obrazów, wizualizowanie słów", "Craik i Lockhart 1972", "fizyczny → fonetyczny → semantyczny", "głębiej = trwalej"], "u": "wyklad-2.html", "s": "p3"}, {"id": "edukacja/wyklad-2-fiszki:d5d39ef1", "q": "Jakie są strategie poznawcze i ich przykłady dla zadań prostych i złożonych?", "a": "<p><strong>Powtarzanie</strong>: recytowanie; przepisywanie, dosłowne notatki, podkreślanie. <strong>Elaboracja</strong>: mnemotechniki, wyobrażenia; opis własnymi słowami, streszczenia, parafrazowanie. <strong>Organizowanie</strong>: grupowanie; plany, mapy pojęciowe.</p>", "src": "Slajdy W3", "k": ["powtarzanie: recytowanie, podkreślanie", "elaboracja: mnemotechniki, parafraza", "organizowanie: grupowanie, mapy pojęciowe", "proste vs złożone zadania"], "u": "wyklad-2.html", "s": "p4"}, {"id": "edukacja/wyklad-2-fiszki:7ea801b2", "q": "Według jakich kryteriów opisuje się strategie poznawcze?", "a": "<p>Faza procesu pamięciowego; stopień aktywności (aktywne/bierne, głębokie/powierzchowne); zakres stosowalności (specyficzne/ogólne); ukierunkowanie (wewnętrzne/zewnętrzne); rodzaj działań (werbalne/niewerbalne); złożoność (proste/złożone); naturalność (naturalne/sztuczne); racjonalność (racjonalne/magiczne).</p>", "src": "Slajdy W3", "k": ["faza pamięci", "aktywność, zakres, ukierunkowanie", "rodzaj, złożoność", "naturalność, racjonalność"], "u": "wyklad-2.html", "s": "p4"}, {"id": "edukacja/wyklad-2-fiszki:5a098e28", "q": "Z czego składają się strategie metapoznawcze?", "a": "<p><strong>Planowanie</strong> (kolejność, czas, miejsce, cele, sposób sprawdzenia), <strong>zarządzanie uczeniem się</strong> (sprawdzone sposoby, warunki, okazje do przećwiczenia, koncentracja), <strong>monitorowanie</strong> (postępy i zrozumienie w trakcie nauki) i <strong>ewaluacja</strong>.</p>", "src": "Slajdy W3", "k": ["planowanie", "zarządzanie", "monitorowanie", "ewaluacja"], "u": "wyklad-2.html", "s": "p5"}, {"id": "edukacja/wyklad-2-fiszki:c8860bb7", "q": "Co mierzy kwestionariusz MSLQ?", "a": "<p>MSLQ (Pintrich i in., 1991; polska wersja skrócona dla uczniów od 12 lat: Dłużniewska i Kucharczyk) ma skale <strong>motywacyjne</strong> (motywacja wewnętrzna i zewnętrzna, wartość zadania, poczucie kontroli i skuteczności, lęk egzaminacyjny) i <strong>poznawcze</strong> (powtarzanie, elaboracja, organizowanie, myślenie krytyczne, metapoznanie, czas i miejsce, wysiłek, uczenie grupowe, szukanie pomocy).</p>", "src": "Slajdy W3", "k": ["Pintrich i in.", "skale motywacyjne", "skale poznawcze", "zarządzanie zasobami"], "u": "wyklad-2.html", "s": "p5"}, {"id": "edukacja/wyklad-2-fiszki:177a7e68", "q": "Czym jest nauczanie i jak szkoła uczy uczenia się?", "a": "<p>Nauczanie to <strong>organizowanie uczenia się</strong> i pomoc w kształtowaniu aktywnej postawy poznawczej. Szkoła uczy uczenia się <strong>pośrednio</strong> (sposób nauczania i sprawdzania, programy, zmęczenie, rozkład zajęć, atmosfera, testy zewnętrzne) i <strong>bezpośrednio</strong> (lekcje o uczeniu się, strategie w trakcie lekcji). Postawy nauczyciela → prowadzenie lekcji → sprawdzanie → sposoby uczenia się uczniów.</p>", "src": "Slajdy W3", "k": ["organizowanie uczenia się", "wpływ pośredni", "wpływ bezpośredni", "sposób sprawdzania kształtuje naukę"], "u": "wyklad-2.html", "s": "p6"}, {"id": "edukacja/wyklad-2-fiszki:5a5d408b", "q": "Co wykazali Lee i Boo (2022) o stylach nauczania?", "a": "<p>Nauczanie <strong>skoncentrowane na uczniu</strong> zwiększało <strong>zainteresowanie</strong> nauką języka obcego, a nauczanie <strong>skoncentrowane na nauczycielu</strong> poprawiało <strong>wyniki</strong> w nauce.</p>", "src": "Slajdy W3", "k": ["na uczniu → zainteresowanie", "na nauczycielu → wyniki"], "u": "wyklad-2.html", "s": "p6"}, {"id": "edukacja/wyklad-2-fiszki:ecf3cb03", "q": "Skąd uczniowie znają strategie uczenia się i jakich używają (Ledzińska, Czerniawska, Rzeńca)?", "a": "<p>Tylko 18% licealistów zna je ze szkoły (Ledzińska, 1988); w podstawówce ze szkoły ok. 20% uczniów sztywnych i 4% giętkich strategicznie (Czerniawska, 1999). Uczniowie klas III stosują tylko <strong>powierzchowne</strong> strategie (czytanie, powtarzanie, przepisywanie), bez metapoznawczych, a nauczyciele znają niewiele skutecznych strategii (Rzeńca, 2023). Oddziaływania szkoły są pośrednie i mogą być nieskuteczne.</p>", "src": "Slajdy W3", "k": ["18% ze szkoły (Ledzińska)", "sztywni vs giętcy (Czerniawska)", "tylko powierzchowne strategie (Rzeńca)", "nauczyciele znają niewiele"], "u": "wyklad-2.html", "s": "p6"}, {"id": "edukacja/wyklad-3-fiszki:7f407fd1", "q": "Jakie role może pełnić psycholog szkolny według Sokołowskiej?", "a": "<p>„<strong>Człowiek środka</strong>” zanurzony w system szkolny; <strong>ekspert</strong> od wychowania i nauczania, wychodzący w opiniach poza system; <strong>badacz</strong> procesu, sytuacji i relacji wychowawczych; <strong>kreator</strong> nowych ujęć i strategii wychowawczych. Rola ma wymiar frontowy i gabinetowy, a pełna jej realizacja wymaga względnej niezależności od systemu szkoły.</p>", "src": "Sokołowska", "k": ["człowiek środka", "ekspert", "badacz", "kreator", "względna niezależność"], "u": "wyklad-3.html", "s": "s1"}, {"id": "edukacja/wyklad-3-fiszki:0656d800", "q": "Co oznacza postulat Guryckiej, by psycholog był „człowiekiem środka”?", "a": "<p>Psycholog buduje kontakt z dzieckiem, rodzicem i nauczycielem, by rozwiązywać obecne i przyszłe <strong>konflikty wychowawcze</strong> i naprawiać ich wzajemne interakcje; ogólnie – wspiera oddziaływania wychowawcze. Przedmiotem jego zainteresowania jest <strong>interakcja wychowawcza</strong>. Nie wyręcza wychowawców, tylko pomaga im zrozumieć i mądrze kształtować sytuacje wychowawcze.</p>", "src": "Sokołowska", "k": ["kontakt z dzieckiem, rodzicem, nauczycielem", "konflikty wychowawcze", "interakcja wychowawcza", "nie wyręcza"], "u": "wyklad-3.html", "s": "s2"}, {"id": "edukacja/wyklad-3-fiszki:902f215e", "q": "Czym jest interakcja wychowawcza?", "a": "<p>Relacja <strong>dwupodmiotowa</strong> – wpływają na nią i dorosły, i dziecko – oraz <strong>niesymetryczna</strong>: dorosły odpowiada za rozwój dziecka i ma prawo kontroli (większe kompetencje), a wychowanek wnosi własną inicjatywę w zdobywanie doświadczeń. Wychowanie jest „generatorem doświadczeń dziecka”, a każda lekcja ma też wymiar wychowawczy.</p>", "src": "Sokołowska", "k": ["dwupodmiotowa", "niesymetryczna", "odpowiedzialność dorosłego", "inicjatywa wychowanka"], "u": "wyklad-3.html", "s": "s2"}, {"id": "edukacja/wyklad-3-fiszki:1311c850", "q": "Dlaczego psycholog szkolny nie powinien działać jak „pogotowie ratunkowe”?", "a": "<p>Model „pogotowia” (sama interwencja kryzysowa) ogranicza skuteczną pomoc i sprowadza się do wyręczania wychowawców („zarzucanie przypadkami”). Psycholog powinien być <strong>widoczny</strong> w szkole zanim pojawi się problem: monitoring, profilaktyka, promocja, dzielenie się wiedzą. Narzędziem jest np. <strong>monografia klasy</strong> (struktura nieformalna, cechy grupy, pozycje uczniów), przerywająca błędne koło kontaktu tylko w kryzysie.</p>", "src": "Sokołowska", "k": ["ogranicza pomoc, wyręczanie", "obecność przed kryzysem", "monitoring, profilaktyka, promocja", "monografia klasy"], "u": "wyklad-3.html", "s": "s2"}, {"id": "edukacja/wyklad-3-fiszki:ff6e141c", "q": "Na czym polega rola psychologa jako eksperta od wychowania i nauczania?", "a": "<p>Gurycka: psycholog jest najpierw ekspertem od wychowania, potem od nauczania. Potrzebuje szerokiej, aktualizowanej wiedzy i <strong>refleksyjności</strong>. Szkoła nie „uczy i wychowuje”, tylko <strong>stwarza warunki</strong> do rozwoju – powinna uczyć uczenia się (Ledzińska), a nauczyciel potrzebuje przygotowania psychologicznego. Psycholog nie formułuje celów wychowania, tylko monitoruje proces z perspektywy wiedzy o rozwoju (Katra): „praca z”, nie „praca za”.</p>", "src": "Sokołowska", "k": ["najpierw wychowanie, potem nauczanie", "wiedza i refleksyjność", "szkoła stwarza warunki, uczy uczenia się", "nie formułuje celów; praca z, nie za"], "u": "wyklad-3.html", "s": "s3"}, {"id": "edukacja/wyklad-3-fiszki:d6adae93", "q": "Jakie działania obejmuje praca psychologa w szkole według Guryckiej?", "a": "<p>Poradnictwo (diagnoza i pomocna informacja), opiekę i pomoc psychologiczną (towarzyszenie w problemie i przygotowanie na przyszłość), szeroką <strong>edukację psychologiczną</strong>, a także działania <strong>naukowe i popularyzatorskie</strong> – „przetwarzanie dorobku naukowego” na potrzeby szkoły. Zawód to <strong>służebność</strong>, a nie usługa na zlecenie.</p>", "src": "Sokołowska", "k": ["poradnictwo", "opieka i pomoc", "edukacja psychologiczna", "badania i popularyzacja", "służebność"], "u": "wyklad-3.html", "s": "s4"}, {"id": "edukacja/wyklad-3-fiszki:31e6cf3d", "q": "Na czym polega frontowy i gabinetowy wymiar pracy psychologa?", "a": "<p>Metafora Jurkowskiego: niektóre zadania wymagają <strong>gabinetu</strong> (indywidualna diagnoza, rozmowa bez przerywania), inne – bycia „<strong>na froncie</strong>”, w codziennym życiu szkoły. Gabinet bywa sytuacją laboratoryjną – uczeń inaczej funkcjonuje w znanym otoczeniu. Wybór miejsca zależy od sytuacji, potrzeb ucznia i preferencji psychologa. Psycholog nie może biernie czekać na zgłoszenia.</p>", "src": "Sokołowska", "k": ["gabinet – diagnoza, spokojna rozmowa", "front – życie szkoły", "sztuczność gabinetu", "nie czekać biernie"], "u": "wyklad-3.html", "s": "s5"}, {"id": "edukacja/wyklad-3-fiszki:6516d013", "q": "Czym są zewnątrzsystemowe ekspertyzy psychologiczne systemu oświaty?", "a": "<p>Jurkowski uważał je za ukoronowanie pracy psychologa szkolnego: ocena systemu dydaktycznego i wychowawczego w kategoriach <strong>psychologicznych</strong>, niezależnie od doktryn pedagogicznych, z pozycji eksperta nieuwikłanego we wspieranie jednej strony. Psycholog analizuje <strong>funkcje</strong> – zamierzone i niezamierzone konsekwencje (np. pogłębianie stratyfikacji społecznej), a nie formułuje celów. To efektywna forma transferu wiedzy.</p>", "src": "Sokołowska", "k": ["kategorie psychologiczne", "niezależność od doktryn", "funkcje, także niezamierzone", "transfer wiedzy"], "u": "wyklad-3.html", "s": "s6"}, {"id": "edukacja/wyklad-3-fiszki:fb2606d3", "q": "Co oznacza, że psycholog powinien być reprezentantem swojej dziedziny?", "a": "<p>Choć jest formalnie w systemie oświaty, powinien zachować <strong>względną niezależność</strong> od oczekiwań instytucji (Jurkowski) i nie poprzestawać na tym, czego wymagają inni. Ma dzielić się wiedzą o rozwoju (prelekcje, wykłady, podręczniki), by inni dostrzegali ogólne tendencje rozwojowe poza własnym, wąskim doświadczeniem, oraz angażować się w działania naukowo-badawcze.</p>", "src": "Sokołowska", "k": ["względna niezależność", "nie tylko oczekiwania instytucji", "dzielenie się wiedzą", "szersza perspektywa rozwojowa"], "u": "wyklad-3.html", "s": "s6"}, {"id": "edukacja/cwiczenia-1-fiszki:c4cf459d", "q": "Jakie dwie funkcje wychowania wyróżnia Katra i jak je ujmuje?", "a": "<p><strong>Socjalizacyjna:</strong> dziecko ma stać się członkiem wspólnoty przez wpajanie norm społeczno-kulturowych. <strong>Emancypacyjna:</strong> przygotowanie do autonomii i samoregulacji, związanych z poczuciem podmiotowości i odpowiedzialności. Autorka traktuje je jako <strong>komplementarne</strong>.", "src": "Wychowanie, podmiotowość i rola eksperta", "k": ["socjalizacyjna: normy wspólnoty", "emancypacyjna: autonomia i samoregulacja", "komplementarne"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "edukacja/cwiczenia-1-fiszki:8d36018e", "q": "Czym jest podmiotowość według Katry (za Guryckę i Obuchowskim)?", "a": "<p>Atrybutem osoby i stanem jej umysłu: poczuciem, że potrafi projektować własną osobę i postrzegać świat na swój sposób. Oznacza <strong>motywację wewnętrzną</strong>, dojrzałość myślenia, dystans do siebie, refleksję nad zmianami i aktywny stosunek do własnej koncepcji siebie; wiąże się z samowychowaniem, autokracją i planowaniem celów osobistych.</p>", "src": "Wychowanie, podmiotowość i rola eksperta", "k": ["atrybut osoby i stan umysłu", "projektowanie własnej osoby", "motywacja wewnętrzna", "aktywny stosunek do koncepcji siebie"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "edukacja/cwiczenia-1-fiszki:3ea4a78c", "q": "Jakie kompetencje podstawowe wskazuje UE (program „Kreator”) i dlaczego to nie wystarcza?", "a": "<p>Organizowanie własnego uczenia się, skuteczne komunikowanie się, współdziałanie w zespole, twórcze rozwiązywanie problemów, posługiwanie się techniką informacyjną. Sprzyjają funkcjonowaniu we współczesnym świecie, ale <strong>nie wyczerpują</strong> warunków kształtowania podmiotowości, dlatego całość procesu wychowawczego ma ogarniać psycholog jako główny ekspert.</p>", "src": "Wychowanie, podmiotowość i rola eksperta", "k": ["uczenie się, komunikacja, praca w zespole", "rozwiązywanie problemów, technika informacyjna", "nie wyczerpują warunków podmiotowości", "psycholog jako ekspert całości"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "edukacja/cwiczenia-1-fiszki:08f083cd", "q": "Czym różni się perspektywa wewnątrz- od zewnątrzsystemowej (Jurkowski)?", "a": "<p><strong>Wewnątrzsystemowa:</strong> szkoła patrzy na siebie od środka i sprawdza, czy realizowane są jej deklarowane cele wychowawcze. <strong>Zewnątrzsystemowa:</strong> spojrzenie z zewnątrz na rzeczywiste rezultaty zjawisk w szkole, czyli faktyczne skutki dla rozwoju osobowego dziecka i jego podmiotowości.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["wewnątrzsystemowa: realizacja deklarowanych celów", "zewnątrzsystemowa: rzeczywiste skutki dla rozwoju dziecka"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:16946cc9", "q": "Jaki jest podstawowy atrybut roli psychologa szkolnego i jego główne zadanie?", "a": "<p><strong>Atrybut:</strong> autonomia wobec formalnych celów szkoły. <strong>Zadanie:</strong> śledzenie wszystkich skutków oddziaływań wychowawczych w rzeczywistości szkolnej. Psycholog jest ekspertem od wychowania i inicjatorem działań wychowawczo-korekcyjnych, który jednocześnie należy i nie należy do środowiska szkolnego.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["autonomia wobec celów szkoły", "śledzenie wszystkich skutków oddziaływań", "ekspert i inicjator działań", "należy i nie należy do szkoły"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:813b31f7", "q": "Do czego służy ekspertyza psychologa i co wychwytuje?", "a": "<p>Wychwytuje <strong>niezamierzone rezultaty</strong> ważne psychologicznie i społecznie. Jest punktem wyjścia dla działań korekcyjnych i profilaktycznych oraz podstawą postulatów wobec systemu oświaty (np. stwarzanie warunków do rozwoju samoregulacji), co czyni psychologa inicjatorem pożądanych oddziaływań.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["niezamierzone rezultaty", "podstawa działań korekcyjnych i profilaktycznych", "postulaty wobec systemu oświaty"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:7c9d44d1", "q": "Jakie rozbieżności wskazuje psycholog, optymalizując proces wychowania szkolnego?", "a": "<p>Między <strong>deklarowanymi a rzeczywistymi wymaganiami</strong> nauczycieli oraz między <strong>zamierzonymi a rzeczywistymi efektami</strong> pracy dydaktyczno-wychowawczej. Formułuje zalecenia je likwidujące lub zmniejszające i kreuje optymalne sytuacje wychowawcze.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["deklarowane a rzeczywiste wymagania nauczycieli", "zamierzone a rzeczywiste efekty", "zalecenia zmniejszające rozbieżności"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:8a4a86ae", "q": "Dlaczego rola eksperta jest w praktyce niedoceniana i jak psycholog może zyskać autonomię?", "a": "<p>Wymaga wyjścia poza system szkoły i oświaty, a psycholog jest podporządkowany dyrektorowi, więc trudno mu wyjść z roli usługodawcy. Może dążyć do indywidualnej autonomii: oferować potrzebne jego zdaniem działania <strong>bez oczekiwania na zapotrzebowanie zewnętrzne</strong>.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["wymaga wyjścia poza system szkoły", "podporządkowanie dyrektorowi", "oferowanie działań bez zapotrzebowania"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:7867e3a3", "q": "Jakie cztery rodzaje działań wyróżnia Katra i jak są powiązane?", "a": "<p>Monitoring, psychoprofilaktyka, interwencja i promocja. <strong>Monitoring jest bazą</strong> dla pozostałych. Profilaktyka, interwencja i promocja mogą być prowadzone równocześnie albo chronologicznie (np. przy agresji: interwencja, profilaktyka trzeciorzędowa, promocja).</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["monitoring", "psychoprofilaktyka", "interwencja", "promocja", "monitoring bazą dla pozostałych"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:45a13768", "q": "Jakie standardy weryfikacji przyjmuje psycholog w monitoringu i do jakich koncepcji się odwołuje?", "a": "<p><strong>Spójność</strong> założonych celów i rzeczywistych konsekwencji oddziaływań oraz <strong>odpowiedniość</strong> tych konsekwencji wobec nadrzędnego celu (rozwój i samoregulacja dla satysfakcjonującej jakości życia, z prawem do godności i szacunku). Koncepcje: doświadczenia Guryckiej (1979) i interakcji wychowawczych Dryll (2001).</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["spójność celów i konsekwencji", "odpowiedniość wobec nadrzędnego celu (rozwój)", "Gurycka: doświadczenia", "Dryll: interakcje wychowawcze"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:41bfdd43", "q": "Czym różnią się trzy poziomy psychoprofilaktyki i który nie jest zadaniem psychologa szkolnego?", "a": "<p><strong>Pierwszorzędowa:</strong> szeroki krąg, niskie ryzyko, promocja zdrowego stylu życia. <strong>Drugorzędowa:</strong> zachowania ryzykowne już się pojawiły, ale nie chronicznie (agresywni, nieśmiali, odrzuceni). <strong>Trzeciorzędowa:</strong> permanentne zachowania ryzykowne, powrót po leczeniu; <strong>nie należy</strong> do zadań psychologa szkolnego.</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["pierwszorzędowa: szeroki krąg, niskie ryzyko", "drugorzędowa: zachowania ryzykowne się pojawiły", "trzeciorzędowa: utrwalone, po leczeniu", "trzeciorzędowa nie jest zadaniem psychologa szkolnego"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:15dabe9d", "q": "Na czym polega interwencja i promocja w pracy psychologa szkolnego?", "a": "<p><strong>Interwencja:</strong> przy wyraźnych problemach; porady, zalecenia, modyfikacja postaw rodziców i nauczycieli, naprawa błędów wychowawczych, rozwiązywanie konfliktów i mediacje. <strong>Promocja:</strong> tworzenie warunków do wykorzystania potencjału ucznia; kompetencje komunikacyjne, przewidywanie konsekwencji, samoregulacja, podnoszenie samooceny.</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["interwencja przy wyraźnych problemach", "porady, mediacje, rozwiązywanie konfliktów", "promocja: wykorzystanie potencjału ucznia", "samoregulacja, samoocena"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:3aac06a2", "q": "Jakie zasady etyczne obowiązują psychologa (także szkolnego)?", "a": "<p>Tajemnica zawodowa, bezstronność, przejrzystość i rzetelna informacja o zamierzeniach, efektach i celu interakcji, zawieranie jasnej umowy dotyczącej tej interakcji.</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["tajemnica zawodowa", "bezstronność", "przejrzystość i rzetelna informacja", "jasna umowa"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:e43804e7", "q": "Jakie formy i kompetencje obejmuje monitoring w Tabeli 2?", "a": "<p><strong>Formy:</strong> obserwacja i analiza, ekspertyza, monografia klasy, rozmowa lub wywiad, spotkania z klasą, rodzicami i nauczycielami. <strong>Kompetencje:</strong> obserwacja uczestnicząca, monografia klasy, metody socjometryczne, nawiązywanie kontaktu i współpracy ze środowiskiem szkolnym, prowadzenie wywiadu.</p>", "src": "Tabela 2: charakterystyka działań", "k": ["obserwacja i analiza", "ekspertyza, monografia klasy", "wywiad, spotkania", "metody socjometryczne"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "edukacja/cwiczenia-1-fiszki:19acf0bb", "q": "Jakie są formy, funkcje i mechanizmy psychoprofilaktyki w Tabeli 2?", "a": "<p><strong>Formy:</strong> szerzenie wiedzy, perswazja, praca z grupą (warsztaty, treningi). <strong>Funkcje:</strong> podnoszenie kompetencji wychowawczych wychowawców i interpersonalnych wychowanków, odporność na niekorzystne wpływy, samoregulacja. <strong>Mechanizmy:</strong> kształtowanie środowiska przez zmiany w elementach systemu, niwelowanie rozbieżności między wzorcem a stanem faktycznym, samokontrola.</p>", "src": "Tabela 2: charakterystyka działań", "k": ["szerzenie wiedzy, perswazja, praca z grupą", "kompetencje wychowawców i wychowanków", "odporność, samoregulacja", "niwelowanie rozbieżności, samokontrola"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "edukacja/cwiczenia-1-fiszki:c63c5f1f", "q": "Czym według Tabeli 2 charakteryzuje się interwencja, a czym promocja?", "a": "<p><strong>Interwencja:</strong> cel to przywracanie korzystnych warunków wychowawczych; formy to porada, indywidualna pomoc, praca systemowa; mechanizmy to zasoby i strategie radzenia sobie ze stresem, kompensacja, nowe schematy; kompetencje obejmują mediację i arbitraż. <strong>Promocja:</strong> cel to formowanie osobowości zgodnie z potencjałem; formy to kształtowanie środowiska, treningi, warsztaty, wzorce; mechanizmy to nowe schematy i <strong>modelowanie</strong>.</p>", "src": "Tabela 2: charakterystyka działań", "k": ["interwencja: przywracanie korzystnych warunków", "porada, pomoc indywidualna, praca systemowa", "mediacja i arbitraż", "promocja: rozwój zgodnie z potencjałem", "modelowanie"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "edukacja/cwiczenia-1-fiszki:fea4d487", "q": "Czym są umiejętności społeczno-emocjonalne według Eliasa i dlaczego warto je rozwijać razem z poznawczymi?", "a": "<p>Zwane też inteligencją emocjonalną; pozwalają współpracować, skutecznie się uczyć i pełnić role w rodzinie, społeczeństwie i pracy. <strong>Można ich nauczyć</strong> i wpływają pozytywnie na uczenie się. Gdy rozwój poznawczy i społeczno-emocjonalny idą razem, uczniowie lepiej zapamiętują materiał, czują odpowiedzialność i są bardziej zmotywowani.</p>", "src": "Uczenie się poznawcze i społeczno-emocjonalne", "k": ["inteligencja emocjonalna", "współpraca, uczenie się, role społeczne", "można się ich nauczyć", "lepsze zapamiętywanie i motywacja"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "edukacja/cwiczenia-1-fiszki:bf5d2a2d", "q": "Dlaczego inteligencja społeczno-emocjonalna jest „brakującym ogniwem”?", "a": "<p>Łączy zdobywanie wiedzy z umiejętnościami potrzebnymi do sukcesu w szkole, domu, społeczeństwie, pracy i życiu. W szkołach z dobrze realizowanymi programami uczniowie osiągają lepsze wyniki, jest mniej problemów z zachowaniem i lepsze relacje ze środowiskiem.</p>", "src": "Uczenie się poznawcze i społeczno-emocjonalne", "k": ["łączy wiedzę z umiejętnościami do sukcesu", "lepsze wyniki", "mniej problemów z zachowaniem"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "edukacja/cwiczenia-1-fiszki:82ea7084", "q": "Czym jest CASEL i jakie cztery grupy umiejętności wyodrębnił?", "a": "<p>Organizacja non-profit badająca edukację w nurcie SEL, założona w 1994 r. przez Golemana i Growald. Cztery grupy (16 umiejętności): <strong>poznaj siebie i innych</strong>, <strong>podejmuj odpowiedzialne decyzje</strong>, <strong>dbaj o innych</strong>, <strong>wiedz, jak trzeba postępować</strong>.</p>", "src": "Umiejętności społeczno-emocjonalne według CASEL", "k": ["organizacja non-profit SEL (1994, Goleman)", "poznaj siebie i innych", "podejmuj odpowiedzialne decyzje", "dbaj o innych", "wiedz, jak postępować"], "u": "cwiczenia-1.html", "s": "s6"}, {"id": "edukacja/cwiczenia-1-fiszki:ef5700b7", "q": "Co mówią zasady 1–2 Eliasa (życzliwość, umiejętności życiowe)?", "a": "<p><strong>1:</strong> podstawą rozwoju są serdeczne relacje w życzliwym, ale wymagającym otoczeniu (bez strachu, z wyzwaniami; jasne, sprawiedliwe, konsekwentne reguły). <strong>2:</strong> na każdym etapie uczyć praktycznych umiejętności życiowych (lista CASEL), np. włączać jedną umiejętność tygodniowo do rutyny.</p>", "src": "Dziesięć zasad Eliasa: zasady 1–5", "k": ["serdeczne relacje w wymagającym otoczeniu", "jasne, sprawiedliwe reguły", "uczenie umiejętności życiowych"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "edukacja/cwiczenia-1-fiszki:bb4a5322", "q": "Co mówią zasady 3–4 Eliasa (spójna polityka szkoły, cele)?", "a": "<p><strong>3:</strong> spójna polityka szkoły (programy prewencji, zdrowy styl życia, wsparcie dzieci w trudnych sytuacjach); pomoc zwykle pojawia się za późno. <strong>4:</strong> wyznaczanie celów i rozwiązywanie problemów nadaje kierunek uczeniu się; uczniowie bardziej zaangażowani, gdy rozumieją cele i znają strategie rozwiązywania problemów (schemat analizy wydarzeń historycznych).</p>", "src": "Dziesięć zasad Eliasa: zasady 1–5", "k": ["spójna polityka szkoły", "prewencja i wsparcie", "wyznaczanie celów", "rozwiązywanie problemów"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "edukacja/cwiczenia-1-fiszki:60a13d4e", "q": "Co mówi zasada 5 Eliasa o procedurach nauczania?", "a": "<p>Należy stosować <strong>zróżnicowane procedury</strong> odwołujące się do różnych zmysłów i zainteresowań (role, sztuka, taniec, teatr, media cyfrowe), zmieniać formy pracy, dawać regularną konstruktywną informację zwrotną i zadawać pytania otwarte, bo rozwój poznawczy i społeczno-emocjonalny przebiega u uczniów różnie.</p>", "src": "Dziesięć zasad Eliasa: zasady 1–5", "k": ["zróżnicowane procedury", "różne zmysły i zainteresowania", "konstruktywna informacja zwrotna", "pytania otwarte"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "edukacja/cwiczenia-1-fiszki:1407f899", "q": "Co mówią zasady 6–7 Eliasa (społeczność lokalna, rodzice)?", "a": "<p><strong>6:</strong> praca na rzecz społeczności rozwija empatię; fazy: przygotowanie, działanie, refleksja, prezentacja. <strong>7:</strong> współpraca szkoły i domu daje trwalsze efekty; regularnie informować rodziców, umożliwiać spotkania i udział w życiu szkoły.</p>", "src": "Dziesięć zasad Eliasa: zasady 6–10", "k": ["praca dla społeczności rozwija empatię", "przygotowanie, działanie, refleksja, prezentacja", "współpraca szkoły i domu"], "u": "cwiczenia-1.html", "s": "s8"}, {"id": "edukacja/cwiczenia-1-fiszki:9102f74f", "q": "Co mówią zasady 8–9 Eliasa (wdrażanie, nauczyciele)?", "a": "<p><strong>8:</strong> programy wprowadza się stopniowo, jako projekty pilotażowe, a kompetentnie czuje się wdrażający dopiero po 2–3 latach; SEL nie jest osobnym przedmiotem. <strong>9:</strong> skuteczność zależy od ciągłego doskonalenia zawodowego i wsparcia całego personelu, zwłaszcza w pierwszych latach wdrażania.</p>", "src": "Dziesięć zasad Eliasa: zasady 6–10", "k": ["wdrażanie stopniowe, pilotaż", "kompetencja po 2–3 latach", "SEL nie osobnym przedmiotem", "ciągłe doskonalenie personelu"], "u": "cwiczenia-1.html", "s": "s8"}, {"id": "edukacja/cwiczenia-1-fiszki:23c0d649", "q": "Dlaczego zasada 10 Eliasa traktuje ewaluację jako zadanie etyczne?", "a": "<p>Szkoła, przyjmując ucznia, zobowiązuje się przygotować go do przyszłości, ale nie gwarantuje rezultatów, więc ma <strong>etyczny obowiązek monitorowania</strong> i ciągłego udoskonalania pracy. Informacje zbiera z wielu źródeł: opinie szkolonych i szkolących, dokumentacja wdrażania, wyniki różnych grup uczniów, bieżące wydarzenia.</p>", "src": "Dziesięć zasad Eliasa: zasady 6–10", "k": ["szkoła zobowiązuje się przygotować ucznia", "brak gwarancji rezultatów", "obowiązek monitorowania i ulepszania", "dane z wielu źródeł"], "u": "cwiczenia-1.html", "s": "s8"}, {"id": "edukacja/cwiczenia-1-fiszki:e2e6847c", "q": "Jakie główne wnioski formułuje Elias na zakończenie?", "a": "<p>Kształcenie poznawcze i społeczno-emocjonalne staje się nowym standardem podstaw szkolnych. Celem jest szkoła, w której nauka jest doceniana, a talenty rozwijają się swobodnie; każdy uczeń ma inny potencjał. Zadanie wymaga cierpliwości i wielkiego wysiłku.</p>", "src": "Zakończenie", "k": ["nowy standard kształcenia", "nauka doceniana, talenty rozwijane", "różny potencjał uczniów", "cierpliwość i wysiłek"], "u": "cwiczenia-1.html", "s": "s9"}];
